-- Velvet CafeOS single-cafe production schema. Run once in Supabase SQL Editor.
create extension if not exists pgcrypto;
do $$ begin create type public.order_status as enum ('new','accepted','preparing','ready','served','completed','cancelled'); exception when duplicate_object then null; end $$;
do $$ begin create type public.payment_method as enum ('cash','jazzcash','easypaisa','bank_transfer','raast'); exception when duplicate_object then null; end $$;
do $$ begin create type public.payment_status as enum ('pending','paid','failed','refunded'); exception when duplicate_object then null; end $$;
create table if not exists public.staff_profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role text not null check(role in('owner','cashier','kitchen')),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,sort_order int not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id) on delete set null,name text not null,description text,image_url text,price_paisa bigint not null check(price_paisa>=0),cost_paisa bigint check(cost_paisa is null or cost_paisa>=0),is_available boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.cafe_tables(id uuid primary key default gen_random_uuid(),table_number int not null unique check(table_number between 1 and 15),capacity int not null default 2,active boolean not null default true,qr_token uuid not null unique default gen_random_uuid(),created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),order_number bigint generated by default as identity unique,table_id uuid references public.cafe_tables(id),customer_name text,customer_phone text,status public.order_status not null default 'new',payment_method public.payment_method not null default 'cash',payment_status public.payment_status not null default 'pending',subtotal_paisa bigint not null check(subtotal_paisa>=0),discount_paisa bigint not null default 0,tax_paisa bigint not null default 0,total_paisa bigint not null check(total_paisa>=0),special_instructions text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name_snapshot text not null,unit_price_paisa bigint not null,quantity int not null check(quantity>0),line_total_paisa bigint not null,notes text);
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,method public.payment_method not null,status public.payment_status not null default 'pending',amount_paisa bigint not null,provider_reference text,verified_by uuid references auth.users(id),verified_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.inventory_items(id uuid primary key default gen_random_uuid(),name text not null unique,unit text not null default 'pcs',quantity numeric(12,3) not null default 0,low_stock_level numeric(12,3) not null default 0,cost_paisa bigint not null default 0,updated_at timestamptz not null default now());
create table if not exists public.inventory_movements(id uuid primary key default gen_random_uuid(),inventory_item_id uuid not null references public.inventory_items(id),movement_type text not null check(movement_type in('purchase','usage','adjustment')),quantity numeric(12,3) not null,note text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),category text not null,description text not null,amount_paisa bigint not null check(amount_paisa>0),expense_date date not null default current_date,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),action text not null,entity text not null,entity_id text,details jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists orders_created_at_idx on public.orders(created_at desc);create index if not exists orders_status_idx on public.orders(status);create index if not exists order_items_order_id_idx on public.order_items(order_id);
-- Secure defaults: RLS enabled. Add role-specific policies before exposing staff tables to clients.
alter table public.staff_profiles enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.cafe_tables enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.payments enable row level security;alter table public.inventory_items enable row level security;alter table public.inventory_movements enable row level security;alter table public.expenses enable row level security;alter table public.audit_logs enable row level security;
-- Public menu read only; all writes are intended through authenticated server-side routes.
drop policy if exists "public read active categories" on public.categories;create policy "public read active categories" on public.categories for select using(active);
drop policy if exists "public read available products" on public.products;create policy "public read available products" on public.products for select using(is_available);
drop policy if exists "public read active tables" on public.cafe_tables;create policy "public read active tables" on public.cafe_tables for select using(active);
-- Staff may read their own profile only. Do not add broad anon insert/update policies.
drop policy if exists "staff read own profile" on public.staff_profiles;create policy "staff read own profile" on public.staff_profiles for select to authenticated using(id=auth.uid());
insert into public.cafe_tables(table_number,capacity) values(1,2),(2,2),(3,2),(4,2),(5,2),(6,2),(7,2),(8,2),(9,2),(10,2),(11,2),(12,2),(13,2),(14,2),(15,2) on conflict(table_number) do nothing;
